Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
const int mod=1e9+7;
const int N=(1<<20)+5;
int n,lim,ans,p1[N],p2[N];
int flag[10][10],a[10][10],h[10][10][10];
int fpow(int x,int y) {
	int res=1;
	while (y) {
		if (y&1) res=1ll*res*x%mod;
		x=1ll*x*x%mod,y>>=1;
	}
	return res;
}
int inv(int x) { return fpow(x,mod-2); }
bool check(int x,int y,int z) {
	int a[3]={x,y,z},d[3]={0,1,2};
	do {
		if (flag[a[d[0]]][1] && flag[a[d[1]]][2] && flag[a[d[2]]][3]) return 1;
	} while (next_permutation(d,d+3));
	return 0;
}

void dfs1(int P,int x,int y) {
	if (x==7 && y==1) {
		int sta=0;
		for (int i=1; i<=6; i++)
			for (int j=i+1; j<=6; j++)
				for (int k=j+1; k<=6; k++) 
					if (check(i,j,k)) {
						int x=1;
			            while (x==i || x==j || x==k) x++;
			            int y=x+1;
			            while (y==i || y==j || y==k) y++;
			            int z=y+1;
			            while (z==i || z==j || z==k) z++;
			            sta|=h[x][y][z];
					}
		p1[sta]=(p1[sta]+P)%mod;
//		if (P!=0) printf("!!!!! %d %d\n",sta,p1[sta],P);
		return;
	}
	flag[x][y]=1;
	if (y==3) dfs1(1ll*P*a[x][y]%mod,x+1,1);
	else dfs1(1ll*P*a[x][y]%mod,x,y+1);
	flag[x][y]=0;
	if (y==3) dfs1(1ll*P*(mod+1-a[x][y])%mod,x+1,1);
	else dfs1(1ll*P*(mod+1-a[x][y])%mod,x,y+1);
}

void dfs2(int P,int x,int y) {
	if (x==7 && y==4) {
		int sta=0;
		for (int i=1; i<=6; i++)
			for (int j=i+1; j<=6; j++)
				for (int k=j+1; k<=6; k++) 
					if (check(i,j,k)) sta|=h[i][j][k];
		p2[sta]=(p2[sta]+P)%mod;
//		if (P!=0) printf("!!!! %d %d %d\n",sta,p2[sta],P);
		ans=(ans+1ll*p1[lim^sta]*P%mod)%mod;
		return;
	}
	flag[x][y-3]=1;
	if (y==6) dfs2(1ll*P*a[x][y]%mod,x+1,4);
	else dfs2(1ll*P*a[x][y]%mod,x,y+1);
	flag[x][y-3]=0;
	if (y==6) dfs2(1ll*P*(mod+1-a[x][y])%mod,x+1,4);
	else dfs2(1ll*P*(mod+1-a[x][y])%mod,x,y+1);
}

int main() {
	scanf("%d",&n);
	for (int i=1; i<=n; i++)
		for (int j=1; j<=n; j++)
			scanf("%d",&a[i][j]),a[i][j]=1ll*a[i][j]*inv(100)%mod;
	for (int i=n+1; i<=6; i++) a[i][i]=1;
	int tot=0;
    for (int i=1; i<=6; i++)
			for (int j=i+1; j<=6; j++)
				for (int k=j+1; k<=6; k++) 
					h[i][j][k]=1<<tot++;
	dfs1(1,1,1);
//	printf("!!!!!!\n");
	lim=(1<<20)-1;
	for (int i=0; i<=19; i++)
		 for (int j=0; j<=lim; j++) 
		 	if (j>>i&1) p1[j]=(p1[j]+p1[j^1<<i])%mod;
//	printf("!!! %d\n",p1[lim]);
	dfs2(1,1,4);
	ans=(mod+1-ans)%mod;
	printf("%d\n",ans);
	return 0;
}


